CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261006104958_InitialCreate') THEN
    CREATE TABLE "AuditLogs" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "Timestamp" timestamp with time zone NOT NULL,
        "UserId" integer,
        "Username" character varying(256) NOT NULL,
        "Action" character varying(100) NOT NULL,
        "EntityType" character varying(100) NOT NULL,
        "EntityId" character varying(100),
        "Details" text,
        "IpAddress" character varying(64),
        CONSTRAINT "PK_AuditLogs" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261006104958_InitialCreate') THEN
    CREATE TABLE "Roles" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" text NOT NULL,
        CONSTRAINT "PK_Roles" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261006104958_InitialCreate') THEN
    CREATE TABLE "SystemSettings" (
        "Key" character varying(150) NOT NULL,
        "Value" text,
        CONSTRAINT "PK_SystemSettings" PRIMARY KEY ("Key")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261006104958_InitialCreate') THEN
    CREATE TABLE "Users" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Username" character varying(256) NOT NULL,
        "NormalizedUsername" character varying(256) NOT NULL,
        "DisplayName" character varying(256) NOT NULL,
        "Email" character varying(256),
        "Department" character varying(256),
        "PasswordHash" text,
        "ExternalId" text,
        "AuthSource" character varying(32) NOT NULL,
        "IsActive" boolean NOT NULL,
        "MustChangePassword" boolean NOT NULL,
        "FailedLoginCount" integer NOT NULL,
        "LockoutUntil" timestamp with time zone,
        "CreatedAt" timestamp with time zone NOT NULL,
        "LastLoginAt" timestamp with time zone,
        CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261006104958_InitialCreate') THEN
    CREATE TABLE "Contents" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Title" character varying(300) NOT NULL,
        "Description" character varying(2000),
        "Body" text,
        "Type" integer NOT NULL,
        "Status" integer NOT NULL,
        "RequiresAcknowledgment" boolean NOT NULL,
        "Version" integer NOT NULL,
        "ExternalUrl" character varying(1000),
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone,
        "PublishedAt" timestamp with time zone,
        "CreatedById" integer,
        CONSTRAINT "PK_Contents" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Contents_Users_CreatedById" FOREIGN KEY ("CreatedById") REFERENCES "Users" ("Id") ON DELETE SET NULL
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261006104958_InitialCreate') THEN
    CREATE TABLE "UserRoles" (
        "UserId" integer NOT NULL,
        "RoleId" integer NOT NULL,
        CONSTRAINT "PK_UserRoles" PRIMARY KEY ("UserId", "RoleId"),
        CONSTRAINT "FK_UserRoles_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_UserRoles_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261006104958_InitialCreate') THEN
    CREATE TABLE "Assessments" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Title" character varying(300) NOT NULL,
        "Description" character varying(2000),
        "ContentId" integer,
        "PassingPercentage" integer NOT NULL,
        "MaxAttempts" integer NOT NULL,
        "IsPublished" boolean NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone,
        CONSTRAINT "PK_Assessments" PRIMARY KEY ("Id"),
        CONSTRAINT ck_assessment_pass CHECK ("PassingPercentage" BETWEEN 0 AND 100),
        CONSTRAINT "FK_Assessments_Contents_ContentId" FOREIGN KEY ("ContentId") REFERENCES "Contents" ("Id") ON DELETE SET NULL
    );
    END IF;
END $EF$;

DO $EF$
