        "FileName" character varying(300) NOT NULL,
        "StoredPath" character varying(500) NOT NULL,
        "ContentType" character varying(150) NOT NULL,
        "SizeBytes" bigint NOT NULL,
        "Kind" integer NOT NULL,
        "UploadedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_ContentAttachments" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ContentAttachments_Contents_ContentId" FOREIGN KEY ("ContentId") REFERENCES "Contents" ("Id") ON DELETE CASCADE
    );
