        "TotalQuestions" integer NOT NULL,
        "CorrectAnswers" integer NOT NULL,
        "TotalPoints" integer NOT NULL,
        "EarnedPoints" integer NOT NULL,
        "Percentage" numeric(5,2) NOT NULL,
        "PassingPercentageSnapshot" integer NOT NULL,
        "Passed" boolean,
        CONSTRAINT "PK_AssessmentAttempts" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_AssessmentAttempts_Assessments_AssessmentId" FOREIGN KEY ("AssessmentId") REFERENCES "Assessments" ("Id") ON DELETE CASCADE,
